# Let's test for backdoor triggers by creating images with potential triggers
# The trigger is a 3-5 pixel square, 1 pixel in from a corner
# Types: white square, checkerboard, random black/white noise

def add_trigger(img, corner='top_left', pattern='white', size=4):
    """Add a trigger to an image. img is (3,32,32) uint8."""
    img = img.clone()
    if corner == 'top_left':
        r, c = 1, 1
    elif corner == 'top_right':
        r, c = 1, 32 - 1 - size
    elif corner == 'bottom_left':
        r, c = 32 - 1 - size, 1
    elif corner == 'bottom_right':
        r, c = 32 - 1 - size, 32 - 1 - size
    else:
        raise ValueError("Invalid corner")

    if pattern == 'white':
        patch = torch.full((3, size, size), 255, dtype=torch.uint8)
    elif pattern == 'checkerboard':
        patch = torch.zeros((3, size, size), dtype=torch.uint8)
        for i in range(size):
            for j in range(size):
                if (i + j) % 2 == 0:
                    patch[:, i, j] = 255
    elif pattern == 'random':
        patch = torch.randint(0, 2, (3, size, size), dtype=torch.uint8) * 255
    else:
        raise ValueError("Invalid pattern")

    img[:, r:r+size, c:c+size] = patch
    return img

